// Disponibilite des 2 camions (Christophe et Axel) par demi-journee. Calcul en code, pas d'IA.
// Regle de Laurent : ensemble ou un seul des deux au travail = 1 camion pris, 1 libre ; chacun de son cote sur la meme demi-journee = aucun camion libre.
const req = $('Preparer').first().json;
function items(n) { try { const r = $(n).first().json; return (r && r.ok && r.data && r.data.items) || []; } catch (e) { return []; } }
const C = [5069], A = [9965, 5198];
const debut = DateTime.fromISO(req.date, { zone: 'Europe/Paris' }).startOf('day');
const jours = [];
for (let i = 0; i < req.jours; i++) jours.push(debut.plus({ days: i }).toISODate());
const J = {};
jours.forEach(d => { J[d] = { matin: [], aprem: [], caler: [] }; });
const vus = new Set();
const evs = items('Lire interventions').concat(items('Lire RDV'))
  .filter(ev => { if (vus.has(String(ev.id))) return false; vus.add(String(ev.id)); return ev.lifecycleState !== 'cancelled'; })
  .sort((a, b) => String(a.start).localeCompare(String(b.start)));
for (const ev of evs) {
  const dt = DateTime.fromISO(ev.start, { zone: 'utc' }).setZone('Europe/Paris');
  const j = J[dt.toISODate()];
  if (!j) continue;
  const ids = (ev.technicianIds || []).map(Number);
  const c = ids.some(t => C.includes(t)), a = ids.some(t => A.includes(t));
  if (!c && !a) continue;
  const m = String(ev.address || '').match(/(\d{5})[\s,]+(.+)$/);
  const lieu = (m ? m[2].trim() : '') || (ev.client && ev.client.name) || String(ev.title || ev.type || 'intervention').slice(0, 40);
  const e = { qui: c && a ? 'ensemble' : (c ? 'Christophe' : 'Axel'), lieu, heure: dt.toFormat("HH'h'mm") };
  if (ev.codeHoraire === 4) { j.caler.push(e); continue; }
  const min = dt.hour * 60 + dt.minute;
  if (ev.codeHoraire === 3) { j.matin.push(e); j.aprem.push(e); }
  else if (min < 750) j.matin.push(e);
  else j.aprem.push(e);
}
const uniq = arr => [...new Set(arr)];
function verdict(liste) {
  const sc = liste.filter(e => e.qui === 'Christophe'), sa = liste.filter(e => e.qui === 'Axel'), ens = liste.filter(e => e.qui === 'ensemble');
  if (!liste.length) return '2 camions libres (ni Christophe ni Axel ne travaille)';
  if (sc.length && sa.length) return 'aucun camion libre (chacun de son cote : Christophe a ' + uniq(sc.map(e => e.lieu)).join(', ') + ', Axel a ' + uniq(sa.map(e => e.lieu)).join(', ') + ')';
  if (ens.length && !sc.length && !sa.length) return '1 camion libre (Christophe et Axel ensemble a ' + uniq(ens.map(e => e.lieu)).join(', ') + ')';
  const seul = sc.length ? 'Christophe' : 'Axel';
  return '1 camion libre (' + seul + ' a ' + uniq(liste.map(e => e.lieu)).join(', ') + (ens.length ? ', en partie avec ' + (seul === 'Christophe' ? 'Axel' : 'Christophe') : ', l autre ne travaille pas') + ')';
}
const lignes = [];
for (const d of jours) {
  const j = J[d];
  const lib = DateTime.fromISO(d, { zone: 'Europe/Paris' }).setLocale('fr').toFormat('cccc dd/MM');
  lignes.push(lib + ' :');
  lignes.push('Matin : ' + verdict(j.matin));
  lignes.push('Apres-midi : ' + verdict(j.aprem));
  if (j.caler.length) lignes.push('A caler (non compte, peut prendre un camion) : ' + j.caler.map(e => (e.qui === 'ensemble' ? 'Christophe+Axel' : e.qui) + ' a ' + e.lieu).join(' ; '));
}
return [{ json: { resultat: 'Disponibilite des camions (calcul automatique, matin jusqu a 12h30) :\n' + lignes.join('\n') } }];

const i = $input.first().json;
const now = DateTime.now().setZone('Europe/Paris');
let d = DateTime.fromISO(String(i.date_debut || ''), { zone: 'Europe/Paris' });
if (!d.isValid) d = now;
const ecart = d.startOf('day').diff(now.startOf('day'), 'days').days;
if (ecart < -30 || ecart > 120) d = now;
const jours = Math.min(Math.max(parseInt(i.jours || 1, 10) || 1, 1), 14);
return [{ json: { date: d.toISODate(), jours, techIds: ['5069', '9965', '5198'] } }];
